def should_run_flashinfer_autotune(
    model_runner: ModelRunner, *, for_speculative_draft: bool = False
) -> bool:
    """Check if flashinfer autotune should be run."""
    mr = model_runner
    if mr.device != "cuda":
        return False
    if get_exec().kernel.disable_flashinfer_autotune:
        return False
    if get_exec().deterministic.enable_deterministic_inference:
        # Tuned configs are per problem shape, so the reduction order would follow
        # the batch shape.
        return False

    if for_speculative_draft:
        backend_str = (
            get_spec().speculative_moe_runner_backend
            or get_exec().moe.moe_runner_backend
        )
        a2a_backend_str = (
            get_spec().speculative_moe_a2a_backend or get_exec().moe.moe_a2a_backend
        )
    else:
        backend_str = get_exec().moe.moe_runner_backend
        a2a_backend_str = get_exec().moe.moe_a2a_backend

    # Autotune can run before the MoE backend globals are initialized, so read
    # the configured backends -- the draft leaves (`get_spec()`) or the target
    # leaves (`get_exec().moe`) above. CuteDSL v1 bypasses MoeRunner, and its
    # dummy dispatch can exceed DeepEP low-latency's token limit.
    if backend_str == "flashinfer_cutedsl" and a2a_backend_str == "deepep":
        return False

    # TODO smor- support other cases for flashinfer autotune, such as, mamba backend

    moe_needs_autotune = backend_str in [
        "flashinfer_trtllm",
        "flashinfer_trtllm_routed",
        "flashinfer_mxfp4",
        "flashinfer_cutedsl",
        "flashinfer_cutlass",
    ]

    from sglang.srt.layers.quantization.fp4_utils import (
        get_fp4_gemm_runner_backend,
    )

    model_quantization = mr.model_config.quantization
    model_uses_fp4 = model_quantization in (
        "modelopt_fp4",
        "modelopt_mixed",
    )
    fp4_gemm_needs_autotune = model_uses_fp4 and (
        get_fp4_gemm_runner_backend().is_flashinfer_cutlass()
        or get_fp4_gemm_runner_backend().is_flashinfer_cutedsl()
    )

    from sglang.srt.layers.quantization.fp8_utils import (
        flashinfer_per_tensor_fp8_supported,
        resolve_mxfp8_dense_gemm_backend,
    )

    if model_quantization == "mxfp8":
        fp8_gemm_needs_autotune = resolve_mxfp8_dense_gemm_backend().is_flashinfer()
    elif model_quantization in ("modelopt", "modelopt_fp8", "modelopt_mixed"):
        fp8_gemm_needs_autotune = flashinfer_per_tensor_fp8_supported()
    else:
        fp8_gemm_needs_autotune = False

    if not (moe_needs_autotune or fp4_gemm_needs_autotune or fp8_gemm_needs_autotune):
        return False

    if torch.cuda.get_device_capability()[0] < 9:
        return False

    if mr.spec_algorithm.is_speculative():
        return mr.is_draft_worker if for_speculative_draft else not mr.is_draft_worker

    return True

def ensure_nvfp4_moe_layer_for_flashinfer_megamoe(layer: FusedMoE) -> Any:
    mega = _get_or_init_flashinfer_megamoe_layer_state(layer)
    if mega is not None:
        return mega

    if envs.SGLANG_FLASHINFER_CUTEDSL_NVFP4_W4A16.get():
        from flashinfer.moe_ep import Sm100_Bf16_Nvfp4_Bf16_Cutedsl_MegaMoeConfig

        return _ensure_flashinfer_megamoe_layer(
            layer,
            megakernel_config=Sm100_Bf16_Nvfp4_Bf16_Cutedsl_MegaMoeConfig(
                intermediate_size=layer.intermediate_size_per_partition,
                top_k=layer.top_k,
                gate_up_clamp=layer.moe_runner_config.swiglu_limit,
                enable_in_kernel_fc2_reduce=envs.SGLANG_FLASHINFER_MEGAMOE_IN_KERNEL_FC2_REDUCE.get(),
            ),
            w13_scale=layer.w13_weight_scale,
            w2_scale=layer.w2_weight_scale,
        )

elif self.quant_mode == "w4a16":
    if (
        x_sf is not None
        or fc2_input_scale is not None
        or per_token_scale is not None
    ):
        raise ValueError(
            "x_sf, fc2_input_scale, and per_token_scale must be None "
            "when quant_mode='w4a16'"
        )
    runner = self._w4a16_runner
    inputs = [
        x,
        token_selected_experts,
        token_final_scales,
        w1_weight,
        w1_weight_sf,
        w1_alpha,
        w2_weight,
        w2_weight_sf,
        w2_alpha,
        moe_output,
    ]
    activation_name = (
        "Situ" if self.situ_beta is not None else self.activation_type.name
    )
    op_name = f"CuteDslMoEWrapper::run::W4A16::{activation_name}"
else:
    raise RuntimeError(f"Unexpected quant_mode {self.quant_mode!r}")

if runner is None:
    raise RuntimeError(f"{self.quant_mode} runner was not initialized")
if tactic is not None:
    return runner(inputs, tactic=tactic)

_, best_tactic = tuner.choose_one(
    op_name,
    [runner],
    runner.tuning_config,
    inputs,
)
if self.quant_mode in ("w4a4", "w4a8"):
    # Timed tactic runs retain the default async path; only this
    # selected-tactic execution is single-stream while tuning.
    runner_kwargs = {"use_async_memset": not tuner.is_tuning_mode}
elif self.quant_mode == "w4a16":
    runner_kwargs = {}
else:
    raise RuntimeError(f"Unexpected quant_mode {self.quant_mode!r}")
return runner(inputs, tactic=best_tactic, **runner_kwargs)

# Reference-counted tuning mode: is_tuning_mode stays True as long as
# at least one autotune(True) context is active, even if an
# autotune(False) context overlaps on another thread.
try:
    with tuner._lock:
        if tune_mode:
            tuner._active_tuning_contexts += 1
        old_mode = tuner.is_tuning_mode
        tuner.is_tuning_mode = tuner._active_tuning_contexts > 0
        autotune_enabled = tune_mode and not old_mode
    if autotune_enabled:
        logger.info("[Autotuner]: Autotuning process starts ...")
except BaseException:
    if pushed:
        override_stack.pop()
    if skip_ops is not None:
        skip_ops_stack.pop()
    raise

try:
    yield
finally:
    with tuner._lock:
        if tune_mode:
            tuner._active_tuning_contexts -= 1
        tuner.is_tuning_mode = tuner._active_tuning_contexts > 0

