dynamic_dims: list[tuple[Any, ...]] = []

for spec in tuning_config.dynamic_tensor_specs:
    assert callable(spec.gen_tuning_buckets) or isinstance(
        spec.gen_tuning_buckets, (list, tuple)
    ), (
        "The given dynamic dimension must provide a opt value generation function or a list of opt values"
    )
    assert len(spec.input_idx) == len(spec.dim_idx), (
        f"The number of input indices and dimension indices must be the same, got {len(spec.input_idx)} and {len(spec.dim_idx)}"
    )

    if callable(spec.gen_tuning_buckets):
        opt_shapes = spec.gen_tuning_buckets(
            _get_opt(base_profile.shapes[spec.input_idx[0]][spec.dim_idx[0]])
        )
    else:
        opt_shapes = spec.gen_tuning_buckets

    # Normalize candidate buckets to be monotonically non-decreasing and non-empty
    opt_shapes = tuple(sorted(set(opt_shapes)))
    assert len(opt_shapes) > 0, "Empty tuning buckets are not allowed"

def map_to_hybrid_bucket_uncapped(x: int) -> int:
    """One-argument variant for use as a function reference in GEMM tuning.

    Same rounding logic as :func:`map_to_hybrid_bucket` but without the
    ``max_num_tokens`` clamp (the autotuner already handles upper-bound
    clamping via the generated bucket list).
    """
    if x <= 0:
        return 1
    if x <= _PHASE1_END:
        return next_positive_power_of_2(x)
    if x <= _PHASE2_END:
        return _ceil_to_step(x, _PHASE2_STEP)
    if x <= _PHASE3_END:
        return _ceil_to_step(x, _PHASE3_STEP)
    return next_positive_power_of_2(x)

def compute(
    self,
    workspace: Any,
    transformed_weights: TransformedMegaWeights,
    *,
    output: torch.Tensor,
) -> torch.Tensor:
    from ......cute_dsl.megamoe.bf16_nvfp4 import bf16_nvfp4_mega_moe

    try:
        if self._autotune_pending:
            from ......cute_dsl.megamoe.bf16_nvfp4 import (
                autotune_bf16_nvfp4_mega_moe,
            )

            self._autotune_winner = dict(
                autotune_bf16_nvfp4_mega_moe(
                    output,
                    transformed_weights[0],
                    transformed_weights[1],
                    workspace,
                    num_tokens=output.shape[0],
                    gate_up_clamp=self._kernel_config.gate_up_clamp,
                    process_group=(
                        self.ep_comm_group
                        if torch.distributed.is_initialized()
                        else None
                    ),
                )
            )
            self._autotune_pending = False
